//! Synchronous native HTMLFormElement required-field validation.
use super::*;
fn fixture(html:&str,source:&str)->(Document,Forms,Page){
 let mut d=crate::html::parse(html);d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://form-validation.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);let out=p.start(&mut d,&mut f,&[Script{node:0,label:"Synchronous FORM validation witness".into(),source:source.into()}]);assert_eq!(out.errors,0,"{}",p.report());(d,f,p)
}
const HTML:&str="<html><body><form id=owner novalidate><input id=a name=a required><input id=b name=b required></form><input id=external name=c required form=owner><form id=other><input id=d name=d required></form></body></html>";
#[test]
fn form_validation_canonical_methods_and_synchronous_required_result(){
 fixture(HTML,"var form=document.getElementById('owner'),a=document.getElementById('a'),calls='',P=HTMLFormElement.prototype;for(var name of ['checkValidity','reportValidity']){var d=Object.getOwnPropertyDescriptor(P,name);if(!d||typeof d.value!=='function'||d.value.name!==name||d.value.length!==0||!d.writable||!d.enumerable||!d.configurable||form[name]!==d.value||Object.prototype.hasOwnProperty.call(form,name))throw 'canonical '+name;var denied=false;try{d.value.call({});}catch(e){denied=e.name==='TypeError';}if(!denied)throw 'brand';}document.addEventListener('invalid',function(e){if(!e.isTrusted||e.bubbles||!e.cancelable||e.composed)throw 'metadata';calls+=e.target.id;e.preventDefault();},true);if(form.checkValidity()!==false||calls!=='abexternal')throw 'synchronous required '+calls;a.value='A';document.getElementById('b').value='B';document.getElementById('external').value='C';if(form.checkValidity()!==true||form.reportValidity()!==true)throw 'fresh valid';");
}
#[test]
fn form_validation_snapshot_mutations_and_microtasks_wait_until_return(){
 let(d,_,_)=fixture(HTML,"var form=document.getElementById('owner'),a=document.getElementById('a'),b=document.getElementById('b'),c=document.getElementById('external'),order='';a.oninvalid=function(e){order+='a';a.value='fixed';b.value='fixed';b.remove();c.required=false;Promise.resolve().then(function(){order+='m';document.title=order;});e.preventDefault();};b.oninvalid=function(e){if(b.isConnected||e.target!==b)throw 'detached target';order+='b';e.preventDefault();};c.oninvalid=function(e){order+='c';e.preventDefault();};if(form.checkValidity()!==false||order!=='abc')throw 'snapshot/job '+order;order+='r';if(form.checkValidity()!==true)throw 'fresh values';");assert_eq!(d.title,"abcrm");
}
#[test]
fn form_validation_nested_same_and_other_forms_keep_independent_snapshots(){
 fixture(HTML,"var form=document.getElementById('owner'),other=document.getElementById('other'),nested=false,order='';document.getElementById('a').oninvalid=function(e){order+='a';if(!nested){nested=true;if(other.checkValidity()!==false||form.checkValidity()!==false)throw 'nested false';order+='r';}e.preventDefault();};document.getElementById('b').oninvalid=function(e){order+='b';e.preventDefault();};document.getElementById('external').oninvalid=function(e){order+='c';e.preventDefault();};document.getElementById('d').oninvalid=function(e){order+='d';e.preventDefault();};if(form.checkValidity()!==false||order!=='adabcrbc')throw 'nested snapshots '+order;");
}
#[test]
fn form_validation_detached_native_root_and_named_methods_preserve_identity(){
 fixture(HTML,"var form=document.createElement('form'),a=document.getElementById('a'),b=document.getElementById('b'),calls='',C=HTMLFormElement.prototype.checkValidity;form.appendChild(a);form.appendChild(b);document.getElementById('other').addEventListener('invalid',function(){throw 'other root';});a.oninvalid=function(e){calls+='a';e.preventDefault();};form.addEventListener('invalid',function(e){if(e.target!==a)calls+='b';e.preventDefault();},true);if(C.call(form)!==false||calls!=='ab')throw 'detached root '+calls;if(C.call(form)!==false)throw 'borrowed detached operation';var connected=document.getElementById('owner'),named=document.createElement('input');named.name='checkValidity';connected.appendChild(named);if(connected.checkValidity!==named)throw 'connected named mask';if(C.call(connected)!==false)throw 'borrowed masked operation';if(!delete form.reportValidity||typeof form.reportValidity!=='function')throw 'inherited delete';");
}
#[test]
fn form_validation_unavailable_constraints_and_backends_refuse_explicitly(){
 fixture("<html><body><form id=owner><input id=field name=q></form><form id=numberOwner><input id=number type=number></form></body></html>","var form=document.getElementById('owner'),field=document.getElementById('field');for(var name of ['pattern','minlength','maxlength']){field.setAttribute(name,'1');var denied=false;try{form.checkValidity();}catch(e){denied=e instanceof DOMException&&e.name==='NotSupportedError';}if(!denied)throw 'constraint refusal '+name;field.removeAttribute(name);}var numberForm=document.getElementById('numberOwner'),number=document.getElementById('number'),denied=false;try{numberForm.reportValidity();}catch(e){denied=e.name==='NotSupportedError';}if(!denied)throw 'input backend';number.disabled=true;if(numberForm.checkValidity()!==true)throw 'barred unsupported control';for(var target of [document.implementation.createHTMLDocument('inert').createElement('form')]){var denied=false;try{HTMLFormElement.prototype.checkValidity.call(target);}catch(e){denied=e instanceof DOMException&&e.name==='NotSupportedError';}if(!denied)throw 'inert backend';}");
}
#[test]
fn form_validation_check_never_reports_and_canceled_report_clears_old_required_only(){
 let(mut d,mut f,mut p)=fixture(HTML,"var form=document.getElementById('owner');document.addEventListener('invalid',function(e){e.preventDefault();},true);if(form.checkValidity()!==false)throw 'check';");assert_eq!(p.take_validation_report(),None);let out=p.console_eval(&mut d,&mut f,"if(form.reportValidity()!==false)throw 'canceled report';");assert_eq!(out.errors,0,"{}",p.report());assert_eq!(p.take_validation_report(),Some(None));assert_eq!(p.take_focus_request(),None);assert!(p.state.form_validations.is_empty());assert!(p.state.synthetic_dispatches.is_empty());assert!(p.state.created_events.iter().all(|e|!e.dispatching));
}
#[test]
fn form_validation_snapshot_and_dispatch_refusal_cleanup_then_fresh_job(){
 for mode in 0..4{
  let(mut d,mut f,mut p)=fixture(HTML,"");let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("owner")).unwrap();let object=node_handle(owner);p.begin_job();let retained=p.state.retained;let limit=p.state.retained_limit;
  match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=retained,_=>p.state.execution_deadline=Some(Instant::now())};assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.begin_native_form_validation(object,true).is_err());assert_eq!(p.state.retained,retained);assert!(p.state.form_validations.is_empty());
  p.state.retained_limit=limit;p.begin_job();let token=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.begin_native_form_validation(object,true).unwrap();let held=p.state.retained;let storage=f.required_snapshot(&d,owner,0,usize::MAX).unwrap().storage_bytes();p.state.copy_work=0;assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.next_native_form_validation_event(token).is_err());Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.finish_native_form_validation(token);assert_eq!(p.state.retained,held-storage);assert!(p.state.form_validations.is_empty());assert!(p.state.synthetic_dispatches.is_empty());
  p.begin_job();let out=p.console_eval(&mut d,&mut f,"var calls=0;document.addEventListener('invalid',function(e){calls++;e.preventDefault();},true);if(document.getElementById('owner').checkValidity()!==false||calls!==3)throw 'fresh validation';");assert_eq!(out.errors,0,"{}",p.report());assert!(p.state.form_validations.is_empty());
 }
}
#[test]
fn form_validation_fatal_listener_keeps_committed_value_and_unwinds_all_frames(){
 let(mut d,mut f,mut p)=fixture(HTML,"var a=document.getElementById('a'),form=document.getElementById('owner'),other=document.getElementById('other');a.oninvalid=function(){other.checkValidity();};document.getElementById('d').oninvalid=function(){a.value='committed';for(var i=0;i<10000;i++){document.getElementById('a');}};");p.begin_job();p.state.host_work=d.nodes.len()*2+f.controls.len()*f.controls.len()+2*f.validation_metadata_work(&d).unwrap()+1000;assert!(p.runtime.execute("form.reportValidity();",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert!(p.state.form_validations.is_empty());assert!(p.state.synthetic_dispatches.is_empty());assert!(p.state.created_events.iter().all(|e|!e.dispatching));let a=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("a")).unwrap();assert_eq!(f.controls[&a].value.text(),"committed");assert_eq!(p.take_validation_report(),None);
 p.begin_job();let out=p.console_eval(&mut d,&mut f,"a.oninvalid=null;document.getElementById('b').value='B';document.getElementById('external').value='C';if(form.reportValidity()!==true)throw 'fresh validity';");assert_eq!(out.errors,0,"{}",p.report());assert!(p.state.form_validations.is_empty());assert_eq!(p.take_validation_report(),Some(None));
}
#[test]
fn form_validation_saved_child_method_authority_refuses_foreign_and_recovers(){
 let(mut d,mut f,mut p)=fixture(HTML,"var form=document.getElementById('owner'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var check=frame.contentWindow.HTMLFormElement.prototype.checkValidity,calls=0;document.addEventListener('invalid',function(e){calls++;e.preventDefault();},true);");
 p.set_location(&crate::navigation::address("https://foreign-validation.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();let error=p.runtime.execute("check.call(form);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert!(p.state.form_validations.is_empty());assert!(p.state.synthetic_dispatches.is_empty());
 p.set_location(&crate::navigation::address("https://form-validation.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();p.runtime.execute("if(calls!==0||check.call(form)!==false||calls!==3)throw 'authority recovery';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();
}
